std::istringstream in("6\n4 2 4 7 2 9\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("2 4 7 9\n4\n"));

std::istringstream in("3\n5 5 5\n");
